"""Make a freshly installed TASAF MIS usable: Tanzania locations, menus, roles, programmes, task
group and one test user per TASAF role.

A new database (openimis-pgsql image + migrations) has none of these: openIMIS's own sample users
and places only. This script adds the TASAF ones, locks openIMIS's sample users, retires its sample
places, and leaves everything else alone. Safe to run again: it only adds what is missing.

    docker compose exec -T backend python manage.py shell < scripts/demo/bootstrap_fresh.py
    docker compose exec -T -e SEED_PASSWORD='Your-Pass-1' backend python manage.py shell < scripts/demo/bootstrap_fresh.py

Every test user, and Admin, get SEED_PASSWORD (default below). Guide: demo/README.md
"""
import base64
import csv
import gzip
import io
import json
import os
import uuid

from django.core.management import call_command
from django.db import transaction

PASSWORD = os.environ.get('SEED_PASSWORD', 'TasafDemo@2026')
TASK_GROUP = {
    'code': '001',
    'sources': ['import_valid_items', 'calcrule_social_protection', 'IndividualService', 'PaymentCycleService',
                'GroupIndividualService', 'GroupService', 'pct_enrolment'],
    'executors': ['Admin', 'tz_task_triage'],
}


def step(title):
    print(f'\n== {title}')


def admin_user():
    from core.models import InteractiveUser
    admin = InteractiveUser.objects.filter(login_name='Admin', validity_to__isnull=True).first()
    if admin is None:
        raise SystemExit('No Admin user in this database; this script expects a standard openIMIS install.')
    return admin


def load_locations(audit):
    from location.models import Location
    rows = list(csv.reader(io.StringIO(gzip.decompress(base64.b64decode(LOCATIONS)).decode())))
    wanted = {code for code, _n, _t, _p in rows}
    existing = {l.code: l for l in Location.objects.filter(validity_to__isnull=True, code__in=wanted)}
    added = 0
    for level in ('R', 'D', 'W', 'V'):
        batch = []
        for code, name, kind, parent in rows:
            if kind != level or code in existing:
                continue
            batch.append(Location(code=code, name=name[:50], type=kind, parent=existing.get(parent),
                                  audit_user_id=audit))
        Location.objects.bulk_create(batch, batch_size=2000)
        for loc in Location.objects.filter(validity_to__isnull=True, type=level, code__in={l.code for l in batch}):
            existing[loc.code] = loc
        added += len(batch)
    print(f'locations: {added} added, {len(wanted) - added} already present')
    return wanted


def retire_sample_locations(tanzania):
    from core import datetime as core_datetime
    from location.models import Location, UserDistrict
    sample = Location.objects.filter(validity_to__isnull=True).exclude(code__in=tanzania)
    from individual.models import Group, Individual
    used = (set(Group.objects.filter(location__in=sample).values_list('location_id', flat=True))
            | set(Individual.objects.filter(location__in=sample).values_list('location_id', flat=True)))
    retire = sample.exclude(id__in=used)
    now = core_datetime.datetime.now()
    UserDistrict.objects.filter(location__in=retire, validity_to__isnull=True).update(validity_to=now)
    count = retire.update(validity_to=now)
    print(f'openIMIS sample locations retired: {count}' + (f' ({len(used)} kept: in use)' if used else ''))


def module_configs():
    from core.models import ModuleConfiguration
    for module, spec in MODULE_CONFIGS.items():
        row = ModuleConfiguration.objects.filter(module=module, layer=spec['layer']).first()
        if row:
            print(f'config {module}: already present, left as is')
            continue
        ModuleConfiguration.objects.create(
            id=uuid.uuid4(), module=module, layer=spec['layer'], version=spec['version'],
            is_exposed=spec['is_exposed'], config=json.dumps(spec['config']))
        print(f'config {module}: added')


def users(admin):
    from core.models import InteractiveUser, Role
    from core.services.userServices import create_or_update_core_user, create_or_update_interactive_user
    from location.models import Location
    roles = {r.name: r.id for r in Role.objects.filter(validity_to__isnull=True)}
    districts = {l.code: l.id for l in Location.objects.filter(validity_to__isnull=True, type='D')}
    added = 0
    for login, other_names, last_name, role_names, district_codes in USERS:
        if InteractiveUser.objects.filter(login_name=login, validity_to__isnull=True).exists():
            continue
        missing = [r for r in role_names if r not in roles]
        if missing:
            print(f'  {login}: skipped, role not found: {missing}')
            continue
        i_user, _ = create_or_update_interactive_user(None, {
            'username': login, 'other_names': other_names, 'last_name': last_name, 'language': 'en',
            'roles': [roles[r] for r in role_names], 'districts': [districts[c] for c in district_codes if c in districts],
            'password': PASSWORD,
        }, admin.id, False)
        create_or_update_core_user(None, login, i_user=i_user)
        added += 1
    admin.set_password(PASSWORD)
    admin.save()
    create_or_update_core_user(None, 'Admin', i_user=admin)
    print(f'test users: {added} added; Admin password set')


def lock_sample_users():
    from core.apps import CoreConfig
    from core.models import InteractiveUser
    keep = {'Admin'} | {u[0] for u in USERS}
    sample = InteractiveUser.objects.filter(validity_to__isnull=True).exclude(login_name__in=keep)
    count = sample.exclude(password=CoreConfig.locked_user_password_hash).update(
        password=CoreConfig.locked_user_password_hash)
    print(f'openIMIS sample users locked: {count}')


def task_group(admin):
    from core.models import User
    from tasks_management.models import TaskExecutor, TaskGroup
    core_admin = User.objects.filter(username='Admin').first()
    group = TaskGroup.objects.filter(code=TASK_GROUP['code'], is_deleted=False).first()
    if group is None:
        group = TaskGroup(code=TASK_GROUP['code'], completion_policy='ANY',
                          json_ext={'task_sources': TASK_GROUP['sources']})
        group.save(user=core_admin)
        print(f"task group {TASK_GROUP['code']}: added")
    for username in TASK_GROUP['executors']:
        user = User.objects.filter(username=username).first()
        if user and not TaskExecutor.objects.filter(task_group=group, user=user, is_deleted=False).exists():
            TaskExecutor(task_group=group, user=user).save(user=core_admin)


def media_houses():
    from core.models import User
    from communications.management.commands.load_client_media_list import CLIENT, MEDIA_HOUSES
    from communications.models import MediaHouse, MediaHouseCategory
    from communications.services import MediaHouseService
    service = MediaHouseService(User.objects.filter(username='Admin').first())
    categories = {c.code: c for c in MediaHouseCategory.objects.filter(is_deleted=False)}
    added = 0
    for name, code in MEDIA_HOUSES:
        if code not in categories or MediaHouse.objects.filter(name=name, is_deleted=False).exists():
            continue
        if service.create({'name': name, 'category_id': categories[code].id, 'is_active': True,
                           'json_ext': dict(CLIENT)})['success']:
            added += 1
    print(f'media houses: {added} added (organisations only, no personnel)')


def run():
    admin = admin_user()
    step('Roles and rights')
    call_command('seed_tasaf_roles', seed_all=True)
    with transaction.atomic():
        step('Tanzania locations')
        tanzania = load_locations(admin.id)
        retire_sample_locations(tanzania)
        step('Menus and settings')
        module_configs()
        step('Users')
        users(admin)
        lock_sample_users()
        step('Task group for imports and enrolment')
        task_group(admin)
        step('Media houses')
        media_houses()
    step('PCT programme')
    call_command('create_pct_programme')
    print(f'\nDone. Log in as Admin or any tz_* user with password: {PASSWORD}')
    print('Then empty the cache and log in again (demo/README.md).')


